mapper.insert:
INSERT INTO sys_operation_log (
    module, operation_type, operation_desc, request_method, request_url,
    request_params, response_data, operator_id, operator_name, operator_ip,
    operator_location, user_agent, status, error_msg, execution_time, create_time
) VALUES

    (
        #{log.module}, #{log.operationType}, #{log.operationDesc}, #{log.requestMethod}, #{log.requestUrl},
        #{log.requestParams}, #{log.responseData}, #{log.operatorId}, #{log.operatorName}, #{log.operatorIp},
        #{log.operatorLocation}, #{log.userAgent}, #{log.status}, #{log.errorMsg}, #{log.executionTime}, #{log.createTime}
    )

mapper.select:
SELECT COUNT(*) FROM sys_operation_log


        AND module = #{module}


        AND operation_type = #{operationType}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}
